    const int vec_width = target.natural_vector_size(type_of<num_t>());

    Var io("io"), ii("ii");

    init_A.compute_root()
          .split(i, io, ii, init_tile)   // outer = tile index, inner = within-tile
          .vectorize(ii, vec_width)      // SIMD inside each tile
          .parallel(io);                 // tiles in parallel across cores

    init_B.compute_root()
          .split(i, io, ii, init_tile)
          .vectorize(ii, vec_width)
          .parallel(io);

    // Realize into the provided buffers.
    init_A.realize(A);
    init_B.realize(B);
}

