        .bound(k, 0, n - 2)                    // extent in k is n-2 (k = 0 .. n-3)
        .compute_root()
        .split(k, ko_A, ki_A, k_tile)          // outer = tile index, inner = within-tile
        .vectorize(ki_A, vec_width)           // SIMD inside each tile
        .parallel(ko_A);                      // tiles across threads

