    // Use a single reciprocal of n to replace a division per element
    // and hoist common casts into constants to reduce arithmetic.
    Expr n_val   = cast<num_t>(n);
    Expr inv_n   = cast<num_t>(1.0f) / n_val;
    Expr idx     = cast<num_t>(i);
    Expr two     = cast<num_t>(2);
    Expr three   = cast<num_t>(3);

    // A[i] = ((DATA_TYPE) i + 2) / n;
    // B[i] = ((DATA_TYPE) i + 3) / n;
    init_A(i) = (idx + two)   * inv_n;
    init_B(i) = (idx + three) * inv_n;

